import { GAME_LABELS } from '@learny/config/product';
import { addCivilDays, toUserZone } from '@learny/core';

// Justification of the daily session, generated by the code at creation and frozen in
// `activities.config` (SPEC-701 EF-7, ET-5, ADR-0180, ADR-0318). At most three bullets, in the
// stable order: gap first, smoothed load, interleaved modules. No bullet, no section.

export type ReviewGapNature = 'forgetting' | 'confusion' | 'misunderstanding' | 'application';

export interface RationaleGapItem {
  notionLabel: string;
  gapNature: ReviewGapNature;
  /** Detection instant of the gap (`notion_states.gap_detected_at`). */
  gapDetectedAt: string | null;
  format: string;
}

export interface RationaleInput {
  timeZone: string;
  now: Date;
  dueCount: number;
  deferredCount: number;
  deferredTo: string;
  capMinutes: number;
  /** Items of the session that answer an active gap (lacunes en tête). */
  gapItems: readonly RationaleGapItem[];
  /** Distinct module positions covered by the items. */
  modulePositions: readonly number[];
}

const WEEKDAY_LABELS = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];

/** Lowercase weekday name of a civil day (EF-4: « jeudi », never abbreviated). */
export function deferredDayLabel(day: string): string {
  const date = new Date(`${day}T12:00:00Z`);
  if (Number.isNaN(date.getTime())) return day;
  return WEEKDAY_LABELS[date.getUTCDay()] ?? day;
}

function shortDayLabel(instant: string, timeZone: string): string {
  const date = new Date(instant);
  if (Number.isNaN(date.getTime())) return '';
  return new Intl.DateTimeFormat('fr-FR', {
    day: 'numeric',
    month: 'short',
    timeZone,
  }).format(date);
}

function lowercaseFirst(text: string): string {
  return text.charAt(0).toLocaleLowerCase('fr-FR') + text.slice(1);
}

/**
 * Pure bullets of the « Réglé par le tuteur » section (EF-7). The gap bullet exists when at least
 * one selected item answers an active gap; the load bullet when at least one notion was deferred;
 * the interleaving bullet when the items span at least two modules.
 */
export function buildRationale(input: RationaleInput): { label: string; text: string }[] {
  const bullets: { label: string; text: string }[] = [];
  const gap = input.gapItems[0];
  if (gap !== undefined && gap.gapDetectedAt !== null) {
    const games = GAME_LABELS as Record<string, { name: string } | undefined>;
    const game = games[gap.format]?.name ?? gap.format;
    bullets.push({
      label: 'Lacune en priorité',
      text: `${lowercaseFirst(gap.notionLabel)}, oubliée depuis le ${shortDayLabel(
        gap.gapDetectedAt,
        input.timeZone,
      )}, revient en ${lowercaseFirst(game)}.`,
    });
  }
  if (input.deferredCount > 0) {
    const plural = input.deferredCount === 1 ? '' : 's';
    bullets.push({
      label: 'Charge lissée',
      text: `${String(input.deferredCount)} notion${plural} sur ${String(
        input.dueCount,
      )} reportée${plural} à ${deferredDayLabel(input.deferredTo)}, pour rester sous ${String(
        input.capMinutes,
      )} min par jour.`,
    });
  }
  if (new Set(input.modulePositions).size >= 2) {
    bullets.push({
      label: 'Modules mêlés',
      text: 'retrouver la bonne notion parmi d’autres la fixe mieux.',
    });
  }
  return bullets;
}

/** Convenience used by the service: the civil day of `now` plus one, in the user's zone. */
export function nextCivilDay(now: Date, timeZone: string): string {
  return addCivilDays(toUserZone(now, timeZone).date, 1);
}
